Vector Iterators 
#include <vector> 
#include <iostream> 
... 
std::vector<int> vec; 
for (int i=1; i<=5; i++) 
vec.push_back(i); 
for (std::vector<int>::iterator it = vec.begin(); 
it != vec.end(); ++it){ 
std::cout << ' ' << *it; 
} 
//Will print: 1 2 3 4 5 
