Using Functions Pointers 
#include <iostream> 
void my_int_func(int x){ 
std::cout << x << std::endl; 
} 
int main(){ 
void (*foo)(int); 
foo = &my_int_func; // The ampersand is actually optional 
(*foo)(2); // Calls my_int_func 
foo(2); // Same as above line 
return 0; 
} 
